"use client"

import React from "react"
import * as AccordionPrimitive from "@radix-ui/react-accordion"
import { ChevronDownIcon } from "lucide-react"
import { cn as classNames } from "@/lib/utils"

type BaseProps = AccordionContextType & {
	className?: string
	children: React.ReactNode
	ref?: React.Ref<HTMLDivElement>
}

type AccordionSingleProps = {
	interaction?: "single"
	collapsible?: boolean
} & Omit<AccordionPrimitive.AccordionSingleProps, "type" | "collapsible"> &
	BaseProps

type AccordionMultipleProps = {
	interaction: "multiple"
} & Omit<AccordionPrimitive.AccordionMultipleProps, "type"> &
	BaseProps

type AccordionContextType = {
	size?: "sm" | "lg"
	variant?: "box" | "table" | "open"
}

type AccordionProps = AccordionSingleProps | AccordionMultipleProps

type AccordionItemProps = React.ComponentProps<typeof AccordionPrimitive.Item> & {
	className?: string
}
type AccordionTriggerProps = React.ComponentProps<typeof AccordionPrimitive.Trigger> & {
	className?: string
}
type AccordionContentProps = React.ComponentProps<typeof AccordionPrimitive.Content> & {
	className?: string
}

const AccordionContext = React.createContext<AccordionContextType | null>(null)

function useAccordion() {
	const context = React.useContext(AccordionContext)
	if (!context) {
		throw new Error("useAccordion must be used within a <Accordion />")
	}
	return context
}

function Accordion({ size = "sm", variant = "box", interaction = "single", className, children, ...rest }: AccordionProps) {
	const rootProps =
		interaction === "single"
			? {
					...(rest as AccordionPrimitive.AccordionSingleProps),
					type: "single" as const,
					collapsible: (rest as AccordionSingleProps).collapsible ?? true,
				}
			: {
					...(rest as AccordionPrimitive.AccordionMultipleProps),
					type: "multiple" as const,
				}

	return (
		<AccordionContext.Provider value={{ size, variant }}>
			<AccordionPrimitive.Root
				data-slot="accordion"
				className={classNames(
					"w-full",
					size === "sm" ? "text-sm/6" : "text-base/7",
					variant === "table" && "border-stroke rounded-xl border",
					className
				)}
				{...rootProps}>
				{children}
			</AccordionPrimitive.Root>
		</AccordionContext.Provider>
	)
}

Accordion.displayName = "Accordion"

function AccordionItem({ children, className, ...props }: AccordionItemProps) {
	const { variant, size } = useAccordion()
	return (
		<AccordionPrimitive.Item
			data-slot="accordion-item"
			className={classNames(
				"overflow-hidden",
				variant === "box"
					? size === "sm"
						? "border-stroke shadow-2xs mb-1.5 rounded-md border last:mb-0"
						: "border-stroke shadow-2xs mb-2 rounded-md border last:mb-0"
					: "border-b first:rounded-t-xl last:rounded-b-xl last:border-b-0",
				className
			)}
			{...props}>
			{children}
		</AccordionPrimitive.Item>
	)
}

AccordionItem.displayName = "AccordionItem"

function AccordionTrigger({ children, className, ...props }: AccordionTriggerProps) {
	const { size, variant } = useAccordion()
	return (
		<AccordionPrimitive.Header className="flex">
			<AccordionPrimitive.Trigger
				data-slot="accordion-trigger"
				className={classNames(
					"bg-bg1 text-fg1 outline-hidden flex flex-1 cursor-pointer items-center justify-between text-left font-medium transition-all [&[data-state=open]>svg]:rotate-180",
					variant === "open" ? (size === "sm" ? "px-0 py-3" : "px-0 py-4") : size === "sm" ? "px-4 py-3" : "p-4",
					className
				)}
				{...props}>
				{children}
				<ChevronDownIcon
					className={classNames("text-text-tertiary shrink-0 transition-transform duration-200", size === "sm" ? "size-5" : "size-6")}
					aria-hidden
				/>
			</AccordionPrimitive.Trigger>
		</AccordionPrimitive.Header>
	)
}

AccordionTrigger.displayName = "AccordionTrigger"

function AccordionContent({ children, className, ...props }: AccordionContentProps) {
	const { size, variant } = useAccordion()
	return (
		<AccordionPrimitive.Content
			data-slot="accordion-content"
			className={classNames(
				"text-text-secondary overflow-hidden transition-all data-[state=closed]:animate-[accordion-close_0.2s_ease-out] data-[state=open]:animate-[accordion-open_0.2s_ease-out]",
				className
			)}
			{...props}>
			<div className={classNames(variant === "open" ? (size === "sm" ? "px-0 pb-3" : "px-0 pb-4") : size === "sm" ? "px-4 pb-3" : "p-4", "pt-0")}>
				{children}
			</div>
		</AccordionPrimitive.Content>
	)
}

AccordionContent.displayName = "AccordionContent"

export { Accordion, AccordionContent, AccordionItem, AccordionTrigger }

import React from "react"
import { type VariantProps, cva } from "class-variance-authority"
import { cn } from "@/lib/utils"

type AlertProps = React.HTMLAttributes<HTMLDivElement> &
	VariantProps<typeof alertVariants> & {
		title?: string
		message?: string
		icon?: React.ReactNode
		endContent?: React.ReactNode
		children?: React.ReactNode
	}

const alertVariants = cva("w-full rounded-xl p-4 flex items-center justify-center gap-3", {
	variants: {
		color: {
			neutral: "bg-fill-level2",
			primary: "border-primary bg-primary/10 text-primary-text",
			info: "border-info bg-info/10 text-info-text",
			success: "border-success bg-success/10 text-success-text",
			danger: "border-error bg-error/10 text-error-text",
			warning: "border-warning bg-warning/10 text-warning-text",
		},
		variant: {
			default: "",
			bordered: "border bg-transparent",
			strong: "",
			"neutral-outline": "border border-border bg-transparent",
		},
	},
	defaultVariants: {
		color: "neutral",
		variant: "default",
	},
	compoundVariants: [
		{
			color: "neutral",
			variant: "bordered",
			className: "border bg-transparent",
		},
		{
			color: "primary",
			variant: "strong",
			className: "bg-primary text-static-white",
		},
		{
			color: "info",
			variant: "strong",
			className: "bg-info text-static-white",
		},
		{
			color: "success",
			variant: "strong",
			className: "bg-success text-static-white",
		},
		{
			color: "warning",
			variant: "strong",
			className: "bg-warning text-static-white",
		},
		{
			color: "danger",
			variant: "strong",
			className: "bg-error text-static-white",
		},
		{
			color: "neutral",
			variant: "strong",
			className: "bg-text text-inverse-white",
		},
	],
})

function Alert({ color = "neutral", variant = "default", title, message, icon, endContent, className, children, ...props }: AlertProps) {
	const isNeutralOutline = variant === "neutral-outline"
	const hasCustomTextColor = className?.includes("text-")

	// Check if we're using the children pattern
	const hasChildrenOnly = children && !title && !message

	return (
		<div className={cn(alertVariants({ color, variant }), className)} {...props}>
			{icon && <div className="flex-shrink-0">{icon}</div>}

			{hasChildrenOnly ? (
				// Render children directly when no title/message provided
				<div className="flex-grow text-sm">{children}</div>
			) : (
				// Original title/message structure
				<div className="flex flex-grow flex-col">
					{title && (
						<h5 className={cn("text-sm font-semibold", isNeutralOutline && "text-text", isNeutralOutline && hasCustomTextColor && "!text-current")}>
							{title}
						</h5>
					)}
					{message && (
						<p
							className={cn(
								"text-sm",
								isNeutralOutline && "text-text-secondary",
								isNeutralOutline && hasCustomTextColor && "!text-current opacity-80"
							)}>
							{message}
						</p>
					)}
					{children}
				</div>
			)}

			{endContent && <div className="flex-shrink-0">{endContent}</div>}
		</div>
	)
}

export { Alert }

"use client"

import { useState } from "react"
import { type VariantProps, cva } from "class-variance-authority"
import { X } from "lucide-react"
import { cn } from "@/lib/utils"

type BadgeProps = React.HTMLAttributes<HTMLDivElement> &
	Omit<VariantProps<typeof badgeVariants>, "size"> & {
		closable?: boolean
		size?: BadgeSize
		className?: string
	}

type BadgeSize = "20" | "24" | "28" | "32"

const badgeVariants = cva("inline-flex items-center font-medium box-border rounded-md w-fit whitespace-nowrap", {
	variants: {
		variant: {
			"neutral-outline": "outline outline-border-alpha",
			strong: "bg-primary text-static-white font-semibold",
			outline: "text-primary-text outline outline-primary",
			pastel: "bg-primary-focus text-primary-text",
		},
		size: {
			"20": "h-5 px-1.5 text-xs",
			"24": "h-6 px-2 text-xs",
			"28": "h-7 px-2 text-sm",
			"32": "h-8 px-3 text-sm",
		},
	},
	defaultVariants: {
		variant: "neutral-outline",
		size: "24",
	},
})

function Badge({ variant = "neutral-outline", size = "24", closable = false, className, children, ...props }: BadgeProps) {
	const [showBadge, setShowBadge] = useState(true)

	return (
		showBadge && (
			<div className={cn(badgeVariants({ variant, size }), "flex items-center gap-1", className)} {...props}>
				{Array.isArray(children)
					? children.map((child, index) =>
							typeof child === "object" && "type" in child && (child.type === "svg" || typeof child.type === "function") ? (
								<span key={index}>{child}</span>
							) : (
								child
							)
						)
					: children}
				{closable && (
					<X
						onClick={() => setShowBadge(false)}
						className={cn("h-4 w-4", "cursor-pointer font-extrabold", variant === "neutral-outline" && "text-text-disabled")}
					/>
				)}
			</div>
		)
	)
}

export { Badge }

"use client"

import { HTMLAttributes, ReactNode, useState } from "react"
import { VariantProps, cva } from "class-variance-authority"
import { X } from "lucide-react"
import { cn } from "@/lib/utils"

type BannerProps = HTMLAttributes<HTMLDivElement> &
	VariantProps<typeof bannerVariants> & {
		children: ReactNode
		variant?: "primary" | "outline" | "gray" | "destructive"
		closable?: boolean
		className?: string
	}

const bannerVariants = cva("py-2 px-4 flex items-center justify-center gap-2.5 relative text-sm w-full", {
	variants: {
		variant: {
			gray: "bg-fill-level2",
			primary: "bg-primary text-static-white",
			outline: "bg-base  border-b",
			destructive: "bg-error text-static-white",
		},
	},
	defaultVariants: {
		variant: "gray",
	},
})

function Banner({ children, variant = "gray", closable, className = "", ...props }: BannerProps) {
	const [showBanner, setShowBanner] = useState(true)
	function getClosableVariant() {
		if (["primary", "destructive"].includes(variant)) {
			return "text-static-white"
		}
		if (["outline", "gray"].includes(variant)) {
			return "text-text-disabled"
		}
	}

	return (
		showBanner && (
			<div {...props} className={cn(bannerVariants({ variant }), className)}>
				{children}
				{closable && <X size={20} onClick={() => setShowBanner(false)} className={`${getClosableVariant()} absolute right-4 cursor-pointer`} />}
			</div>
		)
	)
}
export { Banner }

"use client"

import React, { useEffect, useState } from "react"
import { ChevronRight, Ellipsis, Slash } from "lucide-react"
import { cn } from "@/lib/utils"
import { Badge } from "./badge"
import { Dropdown, DropdownContent, DropdownGroup, DropdownItem, DropdownTrigger } from "./dropdown"

type BaseProps = React.HTMLAttributes<HTMLElement> & {
	className?: string
	children?: React.ReactNode
}

type BreadcrumbProps = BaseProps & {
	separator?: "default" | "slash"
	maxItems?: number
}

type BreadcrumbItemProps = BaseProps & {
	href?: string
	isCurrent?: boolean
	showSeparator?: boolean
	separator?: "default" | "slash"
}

function Breadcrumb({ children, className = "", separator = "default", maxItems: maxItemsProp = 5, ...props }: BreadcrumbProps) {
	const [maxItems, setMaxItems] = useState(maxItemsProp)

	useEffect(() => {
		const handleResize = () => {
			setMaxItems(window.innerWidth <= 640 ? 2 : window.innerWidth <= 768 ? 3 : window.innerWidth <= 1024 ? 4 : maxItemsProp)
		}

		handleResize()
		window.addEventListener("resize", handleResize)
		return () => window.removeEventListener("resize", handleResize)
	}, [maxItemsProp])

	const childArray = React.Children.toArray(children)
	const shouldShowEllipsis = childArray.length > maxItems
	const visibleItems = shouldShowEllipsis ? [childArray[0], ...childArray.slice(-maxItems + 1)] : childArray
	const invisibleItems = shouldShowEllipsis ? childArray.slice(1, -maxItems + 1) : []

	return (
		<nav className={cn("flex items-center", className)} {...props}>
			<ol className="flex items-center justify-center gap-1.5">
				{visibleItems.map((child, index, array) => {
					if (!React.isValidElement<BreadcrumbItemProps>(child)) return child

					const isLast = index === array.length - 1
					const showEllipsis = shouldShowEllipsis && index === 0

					return (
						<React.Fragment key={child.key ?? index}>
							{React.cloneElement(child, {
								...child.props,
								showSeparator: !isLast || showEllipsis,
								separator,
							})}
							{showEllipsis && (
								<>
									<BreadcrumbItem className="cursor-default hover:no-underline">
										<Dropdown>
											<DropdownTrigger asChild>
												<Badge className="cursor-pointer" size="20">
													<Ellipsis size={16} />
												</Badge>
											</DropdownTrigger>
											<DropdownContent>
												<DropdownGroup>
													{invisibleItems.map((hiddenChild, hiddenIndex) =>
														React.isValidElement<BreadcrumbItemProps>(hiddenChild) ? (
															<DropdownItem key={hiddenChild.key ?? hiddenIndex}>
																<a className="flex items-center justify-start gap-0.5" href={hiddenChild.props.href}>
																	{hiddenChild.props.children}
																</a>
															</DropdownItem>
														) : null
													)}
												</DropdownGroup>
											</DropdownContent>
										</Dropdown>
									</BreadcrumbItem>
									{separator === "slash" ? (
										<Slash size={14} className="stroke-text-tertiary" />
									) : (
										<ChevronRight size={14} className="stroke-text-tertiary" />
									)}
								</>
							)}
						</React.Fragment>
					)
				})}
			</ol>
		</nav>
	)
}
Breadcrumb.displayName = "Breadcrumb"

function BreadcrumbItem({
	children,
	href,
	isCurrent = false,
	className = "",
	showSeparator = false,
	separator = "default",
	...props
}: BreadcrumbItemProps) {
	const Comp = href ? "a" : "span"
	const SeparatorIcon = separator === "slash" ? Slash : ChevronRight

	return (
		<>
			<li className="flex items-center justify-center" {...props}>
				<Comp
					href={href}
					className={cn(
						"flex items-center gap-1 text-sm font-medium transition-colors",
						isCurrent ? "font-medium" : "text-text-secondary",
						href && "hover:underline",
						"[&>svg]:h-full [&>svg]:max-h-5 [&>svg]:w-auto",
						className
					)}>
					{children}
				</Comp>
			</li>
			{showSeparator && <SeparatorIcon size={14} className="stroke-text-tertiary" />}
		</>
	)
}

BreadcrumbItem.displayName = "BreadcrumbItem"

export { Breadcrumb, BreadcrumbItem }

"use client"

import React from "react"
import { type VariantProps, cva } from "class-variance-authority"
import { cn } from "@/lib/utils"

type ButtonProps = VariantProps<typeof buttonVariants> &
	React.ButtonHTMLAttributes<HTMLButtonElement> & {
		className?: string
		children: React.ReactNode
		isIcon?: boolean
		color?: "primary" | "info" | "success" | "error" | "warning"
	}

type ButtonGroupProps = React.HTMLAttributes<HTMLDivElement> & {
	children: React.ReactNode
	variant?: ButtonProps["variant"]
	size?: ButtonProps["size"]
	color?: ButtonProps["color"]
}

const buttonVariants = cva(
	"inline-flex whitespace-nowrap items-center justify-center box-border transition duration-200 transform rounded-lg focus-visible:ring-2 focus-visible:ring-offset-2 focus-visible:ring-offset-bg-base disabled:pointer-events-none w-fit",
	{
		variants: {
			variant: {
				strong: "",
				soft: "",
				outline: "",
				ghost: "",
				"neutral-soft": "bg-bg-base font-medium hover:bg-fill-level1 focus-visible:outline-none focus-visible:ring-border-alpha",
				"neutral-outline":
					"bg-bg-base font-medium outline-1 outline-border-alpha drop-shadow-xs hover:bg-fill-level2 focus-visible:ring-border-alpha",
			},
			size: {
				"28": "[&>svg]:size-4 text-xs",
				"32": "[&>svg]:size-5 text-sm",
				"36": "[&>svg]:size-5 text-sm",
				"40": "[&>svg]:size-5 text-sm",
				"44": "[&>svg]:size-6 text-base",
				"48": "[&>svg]:size-6 text-base",
			},
			isIcon: {
				true: "",
				false: "",
			},
			color: {
				primary: "",
				info: "",
				success: "",
				error: "",
				warning: "",
			},
		},
		defaultVariants: {
			variant: "strong",
			size: "36",
			isIcon: false,
			color: "primary",
		},
		compoundVariants: [
			// Size variants
			{ isIcon: false, size: "28", className: "gap-1.5 h-7 px-2" },
			{ isIcon: false, size: "32", className: "gap-1.5 h-8 px-2.5" },
			{ isIcon: false, size: "36", className: "gap-1.5 h-9 px-3" },
			{ isIcon: false, size: "40", className: "gap-1.5 h-10 px-3.5" },
			{ isIcon: false, size: "44", className: "gap-2 h-11 px-4" },
			{ isIcon: false, size: "48", className: "gap-2 h-12 px-4.5" },
			{ isIcon: true, size: "28", className: "px-1.5 h-7 gap-1.5" },
			{ isIcon: true, size: "32", className: "px-1.5 h-8 gap-1.5" },
			{ isIcon: true, size: "36", className: "px-2 h-9 gap-1.5" },
			{ isIcon: true, size: "40", className: "px-2.5 h-10 gap-1.5" },
			{ isIcon: true, size: "44", className: "px-2.5 h-11 gap-2" },
			{ isIcon: true, size: "48", className: "px-3 h-12 gap-2" },

			// Strong variant + colors
			{
				variant: "strong",
				color: "primary",
				className: "bg-primary font-semibold text-static-white hover:bg-primary-hover focus-visible:ring-primary focus-visible:outline-none",
			},
			{
				variant: "strong",
				color: "info",
				className: "bg-info font-semibold text-static-white hover:bg-info-hover focus-visible:ring-info focus-visible:outline-none",
			},
			{
				variant: "strong",
				color: "success",
				className: "bg-success font-semibold text-static-white hover:bg-success-hover focus-visible:ring-success focus-visible:outline-none",
			},
			{
				variant: "strong",
				color: "error",
				className: "bg-error font-semibold text-static-white hover:bg-error-hover focus-visible:ring-error focus-visible:outline-none",
			},
			{
				variant: "strong",
				color: "warning",
				className: "bg-warning font-semibold text-static-white hover:bg-warning-hover focus-visible:ring-warning focus-visible:outline-none",
			},

			// Soft variant + colors
			{
				variant: "soft",
				color: "primary",
				className: "bg-primary-accent font-medium text-primary hover:bg-primary/15 focus-visible:ring-primary-focus focus-visible:outline-none",
			},
			{
				variant: "soft",
				color: "info",
				className: "bg-info-accent font-medium text-info hover:bg-info/15 focus-visible:ring-info-focus focus-visible:outline-none",
			},
			{
				variant: "soft",
				color: "success",
				className: "bg-success-accent font-medium text-success hover:bg-success/15 focus-visible:ring-success-focus focus-visible:outline-none",
			},
			{
				variant: "soft",
				color: "error",
				className: "bg-error-accent font-medium text-error hover:bg-error/15 focus-visible:ring-error-focus focus-visible:outline-none",
			},
			{
				variant: "soft",
				color: "warning",
				className: "bg-warning-accent font-medium text-warning hover:bg-warning/15 focus-visible:ring-warning-focus focus-visible:outline-none",
			},

			// Outline variant + colors
			{
				variant: "outline",
				color: "primary",
				className: "bg-transparent font-medium outline outline-primary-stroke text-primary hover:bg-primary-accent focus-visible:ring-primary-stroke",
			},
			{
				variant: "outline",
				color: "info",
				className: "bg-transparent font-medium outline outline-info-stroke text-info hover:bg-info-accent focus-visible:ring-info-stroke",
			},
			{
				variant: "outline",
				color: "success",
				className: "bg-transparent font-medium outline outline-success-stroke text-success hover:bg-success-accent focus-visible:ring-success-stroke",
			},
			{
				variant: "outline",
				color: "error",
				className: "bg-transparent font-medium outline outline-error-stroke text-error hover:bg-error-accent focus-visible:ring-error-stroke",
			},
			{
				variant: "outline",
				color: "warning",
				className: "bg-transparent font-medium outline outline-warning-stroke text-warning hover:bg-warning-accent focus-visible:ring-warning-stroke",
			},

			// Ghost variant + colors
			{
				variant: "ghost",
				color: "primary",
				className: "bg-transparent text-primary font-medium hover:bg-primary/10 focus-visible:outline-none focus-visible:ring-primary-focus",
			},
			{
				variant: "ghost",
				color: "info",
				className: "bg-transparent text-info font-medium hover:bg-info/10 focus-visible:outline-none focus-visible:ring-info-focus",
			},
			{
				variant: "ghost",
				color: "success",
				className: "bg-transparent text-success font-medium hover:bg-success/10 focus-visible:outline-none focus-visible:ring-success-focus",
			},
			{
				variant: "ghost",
				color: "error",
				className: "bg-transparent text-error font-medium hover:bg-error/10 focus-visible:outline-none focus-visible:ring-error-focus",
			},
			{
				variant: "ghost",
				color: "warning",
				className: "bg-transparent text-warning font-medium hover:bg-warning/10 focus-visible:outline-none focus-visible:ring-warning-focus",
			},
		],
	}
)

function Button({ variant = "strong", size = "36", isIcon = false, color = "primary", className, children, disabled, ...props }: ButtonProps) {
	// Create a combined class with a special treatment for disabled state
	const combinedClass = cn(
		buttonVariants({ variant, size, isIcon, color }),
		disabled && "opacity-50", // Apply opacity only in disabled state
		className
	)

	return (
		<button className={combinedClass} disabled={disabled} {...props}>
			{children}
		</button>
	)
}
Button.displayName = "Button"

function ButtonGroup({ className, children, variant = "outline", size = "36", color = "primary", ...props }: ButtonGroupProps) {
	const modifiedChildren = React.Children.map(children, (child, index) => {
		if (React.isValidElement(child)) {
			const isFirst = index === 0
			const isLast = index === React.Children.count(children) - 1
			const totalChildren = React.Children.count(children)

			// Define border radius class consistently
			const borderRadiusClass = isFirst ? "rounded-l-lg" : isLast ? "rounded-r-lg" : "rounded-none"

			// Set position for proper z-index layering
			const positionClass = isFirst ? "relative z-10" : `relative z-[${totalChildren - index}]`

			// Special handling for different variants
			let borderFixClass = ""
			if (variant === "outline" || variant === "neutral-outline") {
				// For outline variants, we need to completely eliminate double borders
				borderFixClass = !isFirst ? "border-l-0 -ml-[1px]" : ""
			} else if (variant === "strong" || variant === "neutral-soft") {
				// For solid variants
				borderFixClass = !isFirst ? "-ml-[1px]" : ""
			}

			// Check if this is a Button component that should receive our props
			if (React.isValidElement<ButtonProps>(child)) {
				return React.cloneElement(child, {
					variant,
					size,
					color, // Ensure color is passed to child buttons
					className: cn(
						"rounded-none",
						borderRadiusClass,
						positionClass,
						borderFixClass,
						variant === "outline" && "outline-0 border border-current",
						variant === "neutral-outline" && "outline-0 border border-border-alpha",
						"hover:z-20 focus:z-30",
						child.props.className
					),
				})
			}
		}
		return child
	})

	return (
		<div className={cn("inline-flex", className)} role="group" {...props}>
			{modifiedChildren}
		</div>
	)
}
ButtonGroup.displayName = "ButtonGroup"

export { Button, ButtonGroup }

import React, { useState } from "react"
import { CalendarDate, Time, getLocalTimeZone, parseDate, today } from "@internationalized/date"
import { format } from "date-fns"
import { Check, ChevronLeft, ChevronRight } from "lucide-react"
import { ChevronProps, CustomComponents, DateRange, DayPicker, Modifiers, useDayPicker } from "react-day-picker"
import { cn } from "@/lib/utils"
import { DateRangeShortcut, DateRangeShortcutValues, mockMouseClick } from "./date-picker"
import { Select, SelectItem } from "./select"

/**
 * Convert different form of Date object to
 * native Date object
 * @param selected
 * @returns native Date object in original provided form
 */

// Function to convert CalendarDate to native Date object
export function convertToNativeDate(
	selected: CalendarDate | CalendarDate[] | undefined | { from: CalendarDate; to?: CalendarDate }
): Date | Date[] | undefined | DateRange {
	const timeZone = getLocalTimeZone() // Get the local time zone

	if (selected instanceof Array) {
		return selected.map((date) => date.toDate(timeZone))
	}
	if (selected && "from" in selected && "to" in selected) {
		return {
			from: selected.from.toDate(timeZone),
			to: selected?.to?.toDate(timeZone),
		}
	}
	if (selected instanceof CalendarDate) {
		return selected.toDate(timeZone)
	}
	return undefined
}

// Define the calendar component
function convertToInternationalizedDate(
	selected: Date | Date[] | undefined | DateRange
): CalendarDate | CalendarDate[] | undefined | { from: CalendarDate; to?: CalendarDate } {
	if (!selected) return undefined

	if (selected instanceof Array) {
		return selected.map((date) => parseDate(format(date, "yyyy-MM-dd")))
	}
	if (selected && "from" in selected && "to" in selected) {
		return {
			from: parseDate(format(selected.from!, "yyyy-MM-dd")),
			to: selected?.to ? parseDate(format(selected.to, "yyyy-MM-dd")) : undefined,
		}
	}
	if (selected instanceof Date) {
		return parseDate(format(selected, "yyyy-MM-dd"))
	}
	return undefined
}

export type OnSelectHandler<T> = (selected: T, triggerDate: CalendarDate, modifiers: Modifiers, e: React.MouseEvent | React.KeyboardEvent) => void

// Type definition for CalendarSingleSelect props
export type CalendarSingleSelect = {
	mode?: "single"
	selected?: CalendarDate
	onSelect?: OnSelectHandler<CalendarDate | undefined>
	onTimeSelected?: (selectedTime: string) => void
	onSelectIndex?: (index: number) => void
}

// Type definition for CalendarMultipleSelect props
export type CalendarMultipleSelect = {
	mode?: "multiple"
	selected?: CalendarDate[]
	onSelect?: OnSelectHandler<CalendarDate[] | undefined>
}

export type CalendarRange = { from: CalendarDate; to?: CalendarDate }
// Type definition for CalendarRangeSelect props
export type CalendarRangeSelect = {
	mode?: "range"
	selected?: CalendarRange
	onSelect?: OnSelectHandler<CalendarRange | undefined>
}

// Main CalendarProps type combining different selection modes and additional props
export type CalendarProps = Omit<React.ComponentProps<typeof DayPicker>, "selected" | "onSelect" | "numberOfMonths" | "disabled"> &
	(CalendarSingleSelect | CalendarMultipleSelect | CalendarRangeSelect) & {
		dualCalendar?: boolean
		navigatorStyle?: "button" | "selector"
		disabled?: boolean
		showTime?: boolean
		defaultDateRangeShortcutValue?: DateRangeShortcutValues
		showShortcut?: boolean
		footer?: React.ReactNode
		onIndexChange?: (value: string | null) => void
	}
const minTime = "00:00"
const maxTime = "23:59"
const interval = 15

export function generateTimeOptions() {
	const times: Time[] = []
	const [minHour, minMinute] = minTime.split(":").map(Number)
	const [maxHour, maxMinute] = maxTime.split(":").map(Number)

	let currentHour = minHour
	let currentMinute = minMinute

	while (currentHour < maxHour || (currentHour === maxHour && currentMinute <= maxMinute)) {
		const time = new Time(currentHour, currentMinute)
		times.push(time)

		currentMinute += interval
		if (currentMinute >= 60) {
			currentHour += Math.floor(currentMinute / 60)
			currentMinute %= 60
		}
	}

	return times
}

export const timeOptions = generateTimeOptions()

export function formatTime(time: Time) {
	let hour = time.hour
	const minute = String(time.minute).padStart(2, "0")

	const period = hour >= 12 ? "pm" : "am"
	hour = hour % 12
	hour = hour === 0 ? 12 : hour // 12 am/pm handling
	return `${String(hour).padStart(2, "0")}:${minute} ${period}`
}

type TimeSelectorProps = {
	showTime: boolean
	timeOptions: Time[] // Updated to accept Time[]
	selectedIndex: number | null
	setSelectedIndex: (index: number | null) => void
	formatTime: (time: Time) => string // Updated to accept Time
	onTimeSelect?: (formattedTime: string) => void
	mode?: string
}
export function TimeSelector(props: TimeSelectorProps) {
	const { showTime, timeOptions, selectedIndex, setSelectedIndex, formatTime, mode } = props

	if (!showTime) return null

	return (
		<div
			className={`w-30 no-scrollbar flex h-72 flex-col overflow-y-scroll px-1.5 py-1 text-sm font-medium ${mode === "type" ? "bg-fill-level1 text-text-disabled cursor-not-allowed" : "text-text"}`}>
			<p className="text-text-tertiary h-8 rounded-sm px-2 py-2.5 text-xs font-medium">SELECT TIME</p>
			{timeOptions.map((time, index) => {
				const formatted = formatTime(time)
				const isSelected = selectedIndex === index

				return (
					<span
						key={index}
						className={`${mode === "type" ? "text-text-disabled cursor-not-allowed" : "text-text hover:bg-fill-level2 cursor-pointer"} text-text group flex flex-nowrap items-center justify-between gap-2 rounded-sm px-2 py-1.5 text-sm font-normal leading-5`}
						data-value={time}
						onClick={() => {
							setSelectedIndex(index)
							props.onTimeSelect?.(formatted)
						}}>
						{formatted}
						{isSelected && mode !== "type" ? <Check className="stroke-text-secondary" size={16} /> : <span className="size-4" />}
					</span>
				)
			})}
		</div>
	)
}

// Calendar component definition
function CalendarComponent({
	selected,
	onSelect,
	mode = "single",
	onSelect: customOnSelect,
	classNames,
	showShortcut = true,
	components,
	showOutsideDays = true,
	navigatorStyle = "button",
	showTime = false,
	dualCalendar = false,
	defaultDateRangeShortcutValue,
	className,
	footer,
	onIndexChange,
	...props
}: CalendarProps) {
	const [selectedIndex, setSelectedIndex] = useState<number | null>(null)

	const [internalSelected, setInternalSelected] = React.useState<Date | Date[] | DateRange | undefined>(convertToNativeDate(selected))
	const isControlled = selected !== undefined
	const currentSelected = isControlled ? convertToNativeDate(selected) : internalSelected
	let hideCaption: boolean = false

	// Effect to update internal selected state when external selected changes
	React.useEffect(
		function () {
			setInternalSelected(convertToNativeDate(selected))
		},
		[selected]
	)

	const mergedClassName = cn(`p-3 bg-bg-level1 ${showTime ? " border-r" : ""}`, className)

	// Merged class names for styling
	const mergedClassNames: Record<string, string> = {
		root: cn({ "cursor-not-allowed": props.disabled }),
		months: cn("relative flex flex-col bg-bg-level1 w-full gap-5 p-0", {
			"flex-row pt-10": navigatorStyle === "selector",
			"sm:flex-row": navigatorStyle !== "selector",
		}),
		month_caption: cn("mx-10 flex items-center justify-center z-20 p-0 text-sm font-semibold h-7", {
			hidden: props.hideNavigation || hideCaption || (navigatorStyle === "selector" && !dualCalendar),
		}),
		nav: "absolute top-0 flex w-full justify-between z-10 p-0",
		month: "flex flex-col gap-3",
		month_grid: "flex flex-col gap-1.5 items-center",
		weekdays: "w-full flex gap-1.5",
		weekday: "text-text-tertiary text-sm font-medium size-8 shrink-0 flex items-center justify-center",
		weeks: "w-full flex flex-col gap-1.5",
		week: "w-full flex gap-1.5",
		day: "size-8 p-0 shrink-0 group text-sm aria-selected:opacity-100",
		day_button:
			"text-center rounded-lg text-text text-sm font-medium hover:bg-bg-level1 size-8 p-0 hover:group-data-selected:bg-primary group-data-disabled:pointer-events-none group-data-selected:bg-primary hover:group-[.rdp-outside]:group-data-selected:bg-primary/10 group-[.rdp-outside]:group-data-selected:bg-primary/10 group-[.rdp-outside]:group-data-selected:text-text-tertiary group-data-selected:text-white group-data-disabled:text-text-tertiary group-data-outside:text-text-tertiary group-data-today:border group-data-today:border-primary hover:group-[.range-middle]:group-data-selected:bg-primary/10 group-[.range-middle]:group-data-selected:bg-primary/10 group-[.range-middle]:group-data-selected:text-text group-data-selected:group-data-outside:text-white",
		button_previous: cn("border rounded-lg border-border drop-shadow-xs p-1.5 flex justify-center items-center size-7", {
			"pointer-events-none": props.disabled,
		}),
		button_next: cn("border rounded-lg border-border drop-shadow-xs p-1.5 flex justify-center items-center size-7", {
			"pointer-events-none": props.disabled,
		}),
		range_start: "range-start",
		range_middle: "range-middle",
		range_end: "range-end",
		...classNames,
	}

	// Custom components for the calendar
	const customComponents: Partial<CustomComponents> = {}
	if (navigatorStyle === "selector") {
		hideCaption = false
		customComponents["Nav"] = () => <SelectorNavigator localeCode={props.locale?.code as Intl.LocalesArgument} />
	}

	// Merged components including custom ones
	const mergedComponents = {
		Chevron: (props: ChevronProps) => {
			if (props.orientation === "left") return <ChevronLeft size={16} className="stroke-text" />
			return <ChevronRight size={16} className="stroke-text" />
		},
		...customComponents,
		...components,
	}

	// Handle selection of dates
	function handleOnSelect(
		selected: Date | Date[] | undefined | DateRange,
		triggerDate: Date,
		modifiers: Modifiers,
		e: React.MouseEvent | React.KeyboardEvent
	) {
		setInternalSelected(selected)

		const convertedSelected = convertToInternationalizedDate(selected)
		const convertedTriggerDate = parseDate(format(triggerDate, "yyyy-MM-dd"))
		customOnSelect?.(convertedSelected as CalendarDate & CalendarDate[] & CalendarRange, convertedTriggerDate, modifiers, e)
	}

	const [selectedShortcut, setSelectedShortcut] = React.useState<string | null>(defaultDateRangeShortcutValue || null)

	function handleShortcutSelect(shortcut: DateRangeShortcutValues) {
		const todayDate = today(getLocalTimeZone())
		const rangeMap: Record<DateRangeShortcutValues, { from: CalendarDate; to: CalendarDate }> = {
			today: { from: todayDate, to: today(getLocalTimeZone()) },
			last_7_days: { from: todayDate.subtract({ weeks: 1 }), to: todayDate },
			last_30_days: { from: todayDate.subtract({ months: 1 }), to: todayDate },
			last_3_months: { from: todayDate.subtract({ months: 3 }), to: todayDate },
			last_6_months: { from: todayDate.subtract({ months: 6 }), to: todayDate },
			last_12_months: {
				from: todayDate.subtract({ months: 12 }),
				to: todayDate,
			},
			custom: { from: todayDate, to: todayDate },
		}

		if (shortcut !== "custom") {
			const range = rangeMap[shortcut]
			onSelectHandler(range, todayDate, {}, mockMouseClick())
		}
		setSelectedShortcut(shortcut)
	}

	function onSelectHandler(
		selected: CalendarDate | CalendarDate[] | CalendarRange | undefined,
		triggerDate: CalendarDate,
		modifiers: Modifiers,
		e: React.MouseEvent | React.KeyboardEvent
	) {
		if (!selected || (selected as CalendarDate[]).length == 0) {
			setInternalSelected(undefined)
			onSelect?.(undefined, triggerDate, modifiers, e)
			return
		}
		const convertedSelected = convertToNativeDate(selected)

		setInternalSelected(convertedSelected)
		onSelect?.(selected as CalendarDate & CalendarDate[] & CalendarRange, triggerDate, modifiers, e)

		if (e.currentTarget?.getAttribute("data-value") == null) setSelectedShortcut("custom")
	}
	// Effect hook to update the internal selected state based on the selected date
	React.useEffect(function () {
		if (defaultDateRangeShortcutValue) {
			handleShortcutSelect(defaultDateRangeShortcutValue)
		}
	}, [])

	if (mode === "single") {
		return (
			<div className="bg-bg-level1 drop-shadow-xs border-border w-fit overflow-hidden rounded-xl border">
				<div className={`flex ${footer ? "border-b" : ""} overflow-hidden`}>
					{showShortcut && <DateRangeShortcut mode="single" handleShortcutSelect={handleShortcutSelect} selectedValue={selectedShortcut} />}
					<DayPicker
						classNames={mergedClassNames}
						components={mergedComponents}
						className={mergedClassName}
						showOutsideDays={showOutsideDays}
						mode="single"
						selected={currentSelected as Date}
						onSelect={handleOnSelect}
						numberOfMonths={dualCalendar ? 2 : 1}
						{...props}
					/>
					{showTime && (
						<TimeSelector
							timeOptions={timeOptions}
							selectedIndex={selectedIndex}
							setSelectedIndex={setSelectedIndex}
							formatTime={formatTime}
							showTime={showTime}
							onTimeSelect={(formatted) => {
								onIndexChange?.(formatted)
							}}
						/>
					)}
				</div>
				<div className="flex w-full justify-end">{footer && footer}</div>
			</div>
		)
	}

	if (mode == "multiple") {
		return (
			<div className="bg-bg-level1 drop-shadow-xs border-border w-fit overflow-hidden rounded-xl border">
				<div className={`flex ${footer ? "border-b" : ""} overflow-hidden`}>
					{showShortcut && <DateRangeShortcut mode="multiple" handleShortcutSelect={handleShortcutSelect} selectedValue={selectedShortcut} />}
					<DayPicker
						classNames={mergedClassNames}
						components={mergedComponents}
						className={mergedClassName}
						showOutsideDays={showOutsideDays}
						mode="multiple"
						selected={currentSelected as Date[]}
						onSelect={handleOnSelect}
						numberOfMonths={dualCalendar ? 2 : 1}
						{...props}
					/>
					{showTime && (
						<TimeSelector
							timeOptions={timeOptions}
							selectedIndex={selectedIndex}
							setSelectedIndex={setSelectedIndex}
							formatTime={formatTime}
							showTime={showTime}
							onTimeSelect={(formatted) => {
								onIndexChange?.(formatted)
							}}
						/>
					)}
				</div>
				<div className="flex w-full justify-end">{footer && footer}</div>
			</div>
		)
	}

	return (
		<div className="bg-bg-level1 drop-shadow-xs border-border w-fit overflow-hidden rounded-xl border">
			<div className={`flex ${footer ? "border-b" : ""} overflow-hidden`}>
				{showShortcut && <DateRangeShortcut handleShortcutSelect={handleShortcutSelect} selectedValue={selectedShortcut} />}
				<DayPicker
					classNames={mergedClassNames}
					components={mergedComponents}
					className={mergedClassName}
					showOutsideDays={showOutsideDays}
					mode="range"
					selected={currentSelected as DateRange}
					onSelect={handleOnSelect}
					numberOfMonths={dualCalendar ? 2 : 1}
					{...props}
				/>
				{showTime && (
					<TimeSelector
						timeOptions={timeOptions}
						selectedIndex={selectedIndex}
						setSelectedIndex={setSelectedIndex}
						formatTime={formatTime}
						showTime={showTime}
						onTimeSelect={(formatted) => {
							onIndexChange?.(formatted)
						}}
					/>
				)}
			</div>
			<div className="flex w-full justify-end">{footer && footer}</div>
		</div>
	)
}

export function SelectorNavigator({
	localeCode = "en-US",
	minYear = new Date().getFullYear() - 5,
	maxYear = new Date().getFullYear() + 5,
}: {
	localeCode?: Intl.LocalesArgument
	minYear?: number
	maxYear?: number
}) {
	const { months, goToMonth } = useDayPicker()
	const pickedYear = months[0].date.getFullYear()
	const allMonths = Array.from({ length: 12 }, function (_, i) {
		return {
			name: new Intl.DateTimeFormat(localeCode, { month: "long" }).format(new Date(pickedYear, i)),
			date: new Date(pickedYear, i),
		}
	})
	const years = Array.from({ length: maxYear - minYear + 1 }, (_, index) => minYear + index)
	const [year, setYear] = React.useState<string[]>([pickedYear.toString()])

	return (
		<div className="absolute top-0 flex h-fit w-full gap-1.5">
			<Select
				selectedValues={[months[0].date.getMonth().toString()]}
				onSelectedChange={function (values) {
					goToMonth(new Date(pickedYear, parseInt(values[0])))
				}}
				placeholder="Month"
				classNames={{ content: "max-h-60 z-50" }}
				minSelectionCount={1}
				size="36">
				{allMonths.map((month, i) => (
					<SelectItem key={i} value={month.date.getMonth().toString()}>
						{month.name}
					</SelectItem>
				))}
			</Select>
			<Select
				placeholder="Year"
				selectedValues={year}
				onSelectedChange={function (years) {
					setYear(years)
					goToMonth(new Date(parseInt(years[0]), months[0].date.getMonth()))
				}}
				classNames={{ content: "max-h-60 z-50" }}
				minSelectionCount={1}
				size="36">
				{years.map((year) => (
					<SelectItem key={year} value={year.toString()}>
						{year}
					</SelectItem>
				))}
			</Select>
		</div>
	)
}

