"use client"

import React from "react"
import { cva } from "class-variance-authority"
import { OTPInput as OTP, REGEXP_ONLY_DIGITS, REGEXP_ONLY_DIGITS_AND_CHARS, type SlotProps } from "input-otp"
import { cn } from "@/lib/utils"
import { Input, RoundedOptions, SizeOptions, cvaInputVariants, defaultInputRadius, defaultInputSize } from "./input"
import { Label } from "./label"

// Variants for the container of the OTP input
const otpContainerVariants = cva("", {
	variants: {
		variant: { box: "flex w-fit gap-1.5 select-none", flat: "" },
	},
	defaultVariants: { variant: "box" },
})
// Variants for the slots of the OTP input
const otpSlotVariants = cva("", {
	variants: {
		...cvaInputVariants,
		variant: {
			box: "relative text-text flex items-center justify-center transition-all duration-300 border border-border bg-bg-base drop-shadow-xs",
			flat: "",
		},
		size: {
			"28": "size-7 text-xs",
			"32": "size-8 text-sm",
			"36": "size-9 text-sm",
			"40": "size-10 text-sm",
			"44": "size-11 text-sm",
			"48": "size-12 text-base",
			"56": "size-14 text-base",
		},
	},
	defaultVariants: { variant: "box", size: defaultInputSize },
})
// Type definition for OTP input props, extending OTP component props
type OTPInputProps = Pick<
	React.ComponentPropsWithoutRef<typeof OTP>,
	| "value"
	| "onChange"
	| "containerClassName"
	| "onComplete"
	| "placeholder"
	| "textAlign"
	| "inputMode"
	| "pattern"
	| "pasteTransformer"
	| "pushPasswordManagerStrategy"
	| "noScriptCSSFallback"
	| "className"
	| "disabled"
> & {
	length?: number
	variant?: "box" | "flat"
	label?: string
	placeholder?: string
	id?: string
	size?: SizeOptions
	rounded?: RoundedOptions
}
// OTPInput component definition
function OTPInput({
	length = 6,
	variant = "box",
	label,
	placeholder,
	id,
	onChange,
	size = defaultInputSize,
	rounded = defaultInputRadius,
	className,
	...props
}: OTPInputProps) {
	// Value for the flat variant
	const [value, setValue] = React.useState<string>("")
	const inputRef = React.useRef<HTMLInputElement>(null)
	// If the variant is flat, render a simple Input component
	if (variant == "flat") {
		return (
			<Input
				ref={inputRef}
				label={label}
				placeholder={placeholder}
				value={value}
				size={size}
				rounded={rounded}
				className={cn(otpContainerVariants({ variant }), className)}
				onChange={(e) => {
					const rawValue = e.target.value
					const regex = props.inputMode === "numeric" ? new RegExp(REGEXP_ONLY_DIGITS) : new RegExp(REGEXP_ONLY_DIGITS_AND_CHARS)

					if (rawValue !== "" && !regex.test(rawValue)) return

					let newValue = rawValue.slice(0, length)

					// If already at max length, replace the last character
					if (newValue.length > length - 1) {
						newValue = value.slice(0, length - 1) + newValue.charAt(newValue.length - 1)
					}

					setValue(newValue)
					onChange?.(newValue)

					if (newValue.length === length) {
						props.onComplete?.(newValue)
					}
				}}
				id={id}
				disabled={props.disabled}
			/>
		)
	}

	return (
		<div className={cn("flex flex-col gap-1.5", className)}>
			{label && (
				<Label
					className={cn("w-fit text-sm font-medium", {
						"text-text-tertiary": props.disabled,
					})}>
					{label}
				</Label>
			)}
			<OTP
				render={({ slots }) => (
					<div className={otpContainerVariants({ variant })}>
						{slots.slice(0, length).map((slot, idx) => (
							<Slot key={idx} variant={variant} size={size} rounded={rounded} {...slot} />
						))}
					</div>
				)}
				placeholder={placeholder}
				maxLength={length}
				pattern={props.inputMode === "numeric" ? REGEXP_ONLY_DIGITS : REGEXP_ONLY_DIGITS_AND_CHARS}
				onChange={onChange}
				disabled={props.disabled}
				className={cn({ "cursor-not-allowed": props.disabled })}
				{...props}
			/>
		</div>
	)
}
// Slot component for individual OTP input slots
function Slot(
	props: SlotProps & {
		variant: "box" | "flat"
		size: SizeOptions
		rounded: RoundedOptions
	}
) {
	const slotRef = React.useRef<HTMLDivElement>(null)
	// Adding event listeners for mouse enter and leave
	React.useEffect(function () {
		if (slotRef.current) {
			slotRef.current.addEventListener("mouseenter", () => {
				slotRef.current?.classList.add("border-border-alpha!")
				slotRef.current?.classList.add("border-2")
			})

			slotRef.current.addEventListener("mouseleave", () => slotRef.current?.classList.remove("border-border-alpha!"))
		}
	}, [])

	return (
		<div
			className={cn(
				otpSlotVariants({
					variant: props.variant,
					size: props.size,
					rounded: props.rounded,
				}),
				{
					"border-primary ring-primary-focus ring-2": props.isActive,
				}
			)}
			ref={slotRef}>
			{props.char !== null ? (
				<div>{props.char}</div>
			) : (
				props.isActive && <div className="animate-caret-blink inline-block h-[1.2rem] w-[0.063rem] bg-current" />
			)}
		</div>
	)
}
export default OTPInput

"use client"

import React from "react"
import { cva } from "class-variance-authority"
import { cn } from "@/lib/utils"
import { Label } from "./label"

export type SizeOptions = "28" | "32" | "36" | "40" | "44" | "48"
export type RoundedOptions = "xs" | "sm" | "md" | "lg" | "xl" | "2xl"

export const cvaInputVariants = {
	rounded: {
		xs: "rounded-xs",
		sm: "rounded-sm",
		md: "rounded-md",
		lg: "rounded-lg",
		xl: "rounded-xl",
		"2xl": "rounded-2xl",
	},
	size: {
		"28": "h-7 text-xs p-1.5",
		"32": "h-8 text-sm px-3 py-1.5",
		"36": "h-9 text-sm px-3 py-2",
		"40": "h-10 text-sm px-3 py-2.5",
		"44": "h-11 text-base py-2.5 px-3.5",
		"48": "h-12 text-base py-3 px-3.5",
	},
}

export const defaultInputSize = "36"
export const defaultInputRadius = "lg"

const sizeHeightMapping = {
	28: "h-4 w-4",
	32: "h-5 w-5",
	36: "h-5 w-5",
	40: "h-5 w-5",
	44: "h-6 w-6",
	48: "h-6 w-6",
}

// Creating a variant for input styles using cva
const inputVariants = cva("flex h-10 w-full items-center justify-center gap-2 border drop-shadow-xs bg-bg-base cursor-text", {
	variants: {
		...cvaInputVariants,
	},
	defaultVariants: {
		size: defaultInputSize,
		rounded: defaultInputRadius,
	},
})
// Type definition for custom class names for various parts of the input
export type InputClassNames = {
	base?: string /* The div that wraps the component */
	label?: string /* The label of the input */
	wrapper?: string /* The wrapper div for the input and icons (used for showing borders) */
	input?: string /* The actual input element used inside */
	error?: string /* The error message */
}
// Type definition for input props, extending standard input attributes
export type InputProps = Omit<React.InputHTMLAttributes<HTMLInputElement>, "size"> & {
	label?: string
	errorMsg?: string
	hasError?: boolean
	custom?: boolean
	type?: "text" | "email" | "url" | "number" | "password"
	/* 
	It is not recommended to use type=password, instead use the <Password> component,
	'password' is added here because the <Password> uses <Input> component under the hood
	*/
	lead?: React.ReactNode
	trial?: React.ReactNode
	size?: SizeOptions
	rounded?: RoundedOptions
	id?: string
	classNames?: InputClassNames
	ref?: React.Ref<HTMLInputElement>
}
// Input component definition
function Input({
	label,
	disabled,
	errorMsg,
	custom = false,
	hasError = false,
	type = "text",
	lead,
	trial,
	size = defaultInputSize,
	rounded = defaultInputRadius,
	id,
	className,
	classNames,
	...props
}: InputProps) {
	let htmlId = React.useId()
	if (id) htmlId = id

	return (
		<div
			className={cn("text-fg-1 flex w-full flex-col items-start gap-1.5 text-sm", { "cursor-not-allowed": disabled }, className, classNames?.base)}>
			{label && (
				<Label htmlFor={htmlId} className={cn({ "text-text-disabled cursor-not-allowed": disabled }, classNames?.label)}>
					{label}
				</Label>
			)}
			<label
				className={cn(
					inputVariants({ size, rounded }),
					{
						// Only show error focus ring when not disabled
						"border-error focus-within:ring-error/10 focus-within:ring-2": hasError && !disabled,

						// Only show regular focus ring when not disabled
						"focus-within:border-primary focus-within:ring-primary/10 border-border-alpha focus-within:ring-2": !hasError && !disabled,

						// Apply disabled styles
						"text-text-disabled bg-fill-level1 cursor-not-allowed drop-shadow-none": disabled,

						[`rounded-r-none`]: custom,
					},
					size === "28" ? "gap-1.5" : "gap-2",
					classNames?.wrapper
				)}>
				{lead && (
					<span
						className={cn("flex cursor-pointer items-center justify-center rounded", {
							"text-text-tertiary": !disabled,
							"text-text-disabled": disabled,
						})}>
						{React.isValidElement(lead)
							? React.cloneElement(lead as React.ReactElement<{ className?: string }>, {
									className: cn((lead as React.ReactElement<{ className?: string }>)?.props?.className || "", sizeHeightMapping[size]),
								})
							: lead}
					</span>
				)}
				<input
					id={htmlId}
					className={cn(
						"text-fg-1 placeholder-text-tertiary outline-hidden h-fit w-full select-none border border-none bg-transparent p-0 text-sm placeholder:text-sm placeholder:font-normal focus:ring-0",
						{
							"text-text-disabled placeholder-text-disabled cursor-not-allowed": disabled,
						},
						size && {
							"text-xs placeholder:text-xs": size === "28",
							"text-sm placeholder:text-sm": ["32", "36", "40"].includes(size),
							"text-base placeholder:text-base": ["44", "48"].includes(size),
						},
						classNames?.input
					)}
					type={type}
					disabled={disabled}
					{...props}
				/>
				{trial && (
					<span
						className={cn("flex cursor-pointer items-center justify-center rounded", {
							"text-text-tertiary": !disabled,
							"text-text-disabled": disabled,
						})}>
						{React.isValidElement(trial)
							? React.cloneElement(trial as React.ReactElement<{ className?: string }>, {
									className: cn((trial as React.ReactElement<{ className?: string }>)?.props?.className || "", sizeHeightMapping[size]),
								})
							: trial}
					</span>
				)}
			</label>
			{hasError && <Label className={cn("text-error flex items-start text-xs font-medium", className)}>{errorMsg}</Label>}
		</div>
	)
}

