import React from "react"
import { Time } from "@internationalized/date"
import { cn } from "@/lib/utils"
import { Select, SelectItem, SelectProps } from "./select"

export type TimePickerProps = Pick<
	SelectProps,
	"className" | "classNames" | "defaultSelected" | "label" | "placeholder" | "rounded" | "size" | "renderTrigger" | "disabled"
> & {
	interval?: number
	value?: Time | null
	onValueChange?: (time: Time | null) => void
	is24Hour?: boolean
	minTime?: string
	maxTime?: string
	defaultValue?: Time
	allowEmptySelection?: boolean
}

/**
 * Converts a Dayjs object to a string in "HH:mm" format.
 * @param time - The Dayjs object to format.
 * @returns The formatted time string.
 */
export function serializeTime(time: Time) {
	const hour = String(time.hour).padStart(2, "0")
	const minute = String(time.minute).padStart(2, "0")
	return `${hour}:${minute}`
}

/**
 * Converts a string in "HH:mm" format to a Time object.
 * @param timeString - The time string to parse.
 * @returns A Time object representing the given time.
 */
function deserializeTime(timeString: string) {
	const [hour, minute] = timeString.split(":").map(Number)
	return new Time(hour, minute)
}

function TimePicker({
	interval = 15,
	onValueChange,
	is24Hour = false,
	minTime = "00:00",
	maxTime = "23:59",
	defaultValue,
	value = null,
	allowEmptySelection = true,
	classNames,
	...props
}: TimePickerProps) {
	const isControlled = value !== null

	/* Store the time as a serialized string ("HH:mm") to simplify comparisons and render */
	const [internalValue, setInternalValue] = React.useState<string[]>(defaultValue ? [serializeTime(defaultValue)] : [])

	const currentValue = isControlled ? serializeTime(value) : internalValue[0]

	/**
	 * Generates an array of Dayjs objects representing selectable time options.
	 *
	 * The function computes times starting from minTime until maxTime using the provided interval.
	 * We choose this approach to support various ranges and intervals without hardcoding values.
	 *
	 * @returns An array of Dayjs objects for each selectable time.
	 */
	function generateTimeOptions() {
		const times: Time[] = []
		const [minHour, minMinute] = minTime.split(":").map(Number)
		const [maxHour, maxMinute] = maxTime.split(":").map(Number)

		let currentHour = minHour
		let currentMinute = minMinute

		while (currentHour < maxHour || (currentHour === maxHour && currentMinute <= maxMinute)) {
			const time = new Time(currentHour, currentMinute)
			times.push(time)

			currentMinute += interval
			if (currentMinute >= 60) {
				currentHour += Math.floor(currentMinute / 60)
				currentMinute %= 60
			}
		}

		return times
	}

	const timeOptions = generateTimeOptions()
	/**
	 * Handles value changes when a user selects a time.
	 * Updates the internal state and calls the onValueChange callback.
	 * @param value - The selected time as a string.
	 */
	function handleChange(value: string | undefined) {
		if (!value) {
			onValueChange?.(null)
			setInternalValue([])
		} else {
			onValueChange?.(deserializeTime(value))
			setInternalValue([value])
		}
	}
	// Formats a Time object into a human-readable string based on 12-hour or 24-hour format.
	function formatTime(time: Time) {
		let hour = time.hour
		const minute = String(time.minute).padStart(2, "0")
		if (!is24Hour) {
			const period = hour >= 12 ? "pm" : "am"
			hour = hour % 12
			hour = hour === 0 ? 12 : hour // 12 am/pm handling
			return `${String(hour).padStart(2, "0")}:${minute} ${period}`
		} else {
			return `${String(hour).padStart(2, "0")}:${minute}`
		}
	}

	return (
		<Select
			selectedValues={[currentValue]}
			onSelectedChange={function (values) {
				handleChange(values[0])
			}}
			classNames={{ content: cn("h-80"), ...classNames }}
			minSelectionCount={allowEmptySelection ? 0 : 1}
			{...props}>
			{timeOptions.map((time, index) => {
				const formatted = formatTime(time)
				return (
					<SelectItem key={index} value={serializeTime(time)}>
						{formatted}
					</SelectItem>
				)
			})}
		</Select>
	)
}

export default TimePicker

"use client"

import * as React from "react"
import * as TooltipPrimitive from "@radix-ui/react-tooltip"
import { cn } from "@/lib/utils"

type TooltipContext = Pick<React.ComponentPropsWithoutRef<typeof TooltipPrimitive.Content>, "align" | "side"> & {
	withArrow?: boolean
}

const TooltipContext = React.createContext<TooltipContext | null>(null)

const useTooltipContext = () => {
	const context = React.useContext(TooltipContext)
	if (!context) throw new Error("useTooltipContext must be used within <Tooltip />")
	return context
}

const TooltipWrapper = ({ children }: { children: React.ReactNode }) => <TooltipPrimitive.Provider>{children}</TooltipPrimitive.Provider>

type TooltipProps = React.ComponentProps<typeof TooltipPrimitive.Root> & TooltipContext

const Tooltip = ({ align = "center", side = "top", withArrow = false, children, ...props }: TooltipProps) => {
	return (
		<TooltipWrapper>
			<TooltipContext.Provider value={{ align, side, withArrow }}>
				<TooltipPrimitive.Root {...props}>{children}</TooltipPrimitive.Root>
			</TooltipContext.Provider>
		</TooltipWrapper>
	)
}
Tooltip.displayName = TooltipPrimitive.Root.displayName

const TooltipTrigger = TooltipPrimitive.Trigger
TooltipTrigger.displayName = TooltipPrimitive.Trigger.displayName

type TooltipContentProps = React.ComponentProps<typeof TooltipPrimitive.Content>
const TooltipContent = ({ className, sideOffset = 6, children, ...props }: TooltipContentProps) => {
	const { align, side, withArrow } = useTooltipContext()

	return (
		<TooltipPrimitive.Content
			align={align}
			side={side}
			sideOffset={sideOffset}
			className={cn(
				"relative",
				"bg-black px-2 py-1 text-center text-xs text-white dark:bg-white dark:text-black",
				// Base animations
				"animate-in fade-in-20 zoom-in-95",
				// Side-specific slide animations
				side === "top"
					? "slide-in-from-bottom-2"
					: side === "bottom"
						? "slide-in-from-top-2"
						: side === "left"
							? "slide-in-from-right-2"
							: "slide-in-from-left-2", // right side

				// Open state animations
				"data-[state=open]:animate-in data-[state=open]:fade-in-20 data-[state=open]:zoom-in-95",
				side === "top"
					? "data-[state=open]:slide-in-from-bottom-2"
					: side === "bottom"
						? "data-[state=open]:slide-in-from-top-2"
						: side === "left"
							? "data-[state=open]:slide-in-from-right-2"
							: "data-[state=open]:slide-in-from-left-2", // right side

				// Closed state animations
				"data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=closed]:zoom-out-95",
				side === "top"
					? "data-[state=closed]:slide-out-to-bottom-2"
					: side === "bottom"
						? "data-[state=closed]:slide-out-to-top-2"
						: side === "left"
							? "data-[state=closed]:slide-out-to-right-2"
							: "data-[state=closed]:slide-out-to-left-2", // right side

				// Timing control
				"data-[state=open]:duration-300",
				"data-[state=closed]:duration-400",

				// Transform origin
				"origin-[var(--radix-tooltip-content-transform-origin)]",

				// Base styles
				"outline-hidden z-50 rounded-md shadow-md",
				className
			)}
			{...props}>
			{children}
			{withArrow && (
				<TooltipPrimitive.Arrow
					offset={10}
					className={cn("z-60 absolute top-[-2px] h-2 w-4 fill-black dark:fill-white", {
						"left-1/2 -translate-x-1/2": align === "center",
						"-translate-x-full": align === "start" && "right",
						"translate-x-6": align === "end" && side === "top",
						"-translate-x-10": align === "start" && side === "top",
						"-translate-x-4": align === "end" && side === "left",
						"-translate-x-1.2": align === "start" && side === "left",
						"translate-x-5": align === "start" && side === "bottom",
						"-translate-x-9": align === "end" && side === "bottom",
					})}
				/>
			)}
		</TooltipPrimitive.Content>
	)
}
TooltipContent.displayName = TooltipPrimitive.Content.displayName

export { Tooltip, TooltipTrigger, TooltipContent }
